#!/usr/bin/env bash
# ally_shaders.sh - status / install / exact revert of the staged Nioh 3 shader swaps on Linux (Bazzite / SteamOS,
# Proton + vkd3d-proton). Same files and SHA-256 checks as gpu-shaders\apply_{ghdm,esm,wdo28,sweep}.ps1 on Windows.
#
#   ./ally_shaders.sh status            [ghdm|esm|wdo28|wdo14|mpc|mshlod|lodu|toonedge2|gi|fogpar|trvs|pbvs|msv|all]
#   ./ally_shaders.sh apply             [ghdm|esm|wdo28|wdo14|mpc|mshlod|lodu|toonedge2|gi|fogpar|trvs|pbvs|msv|all]
#   ./ally_shaders.sh revert            [ghdm|esm|wdo28|wdo14|mpc|mshlod|lodu|toonedge2|gi|fogpar|trvs|pbvs|msv|all]
#
# mpc / toonedge2 = the 2026-10-07 shader sweep (notes/gpu-shader-sweep.md); toonedge2 covers two files.
# mpc = ONE combined 0x29ee0902.file: MPC#23 + the prefix-sum chain #28-#31 (notes/gpu-culling-rewrite.md). It
# supersedes the earlier mpc23-only file (5th column): that one is recognised and upgraded / reverted like ours.
# mshlod = 0x8d9282e6.file: MshLod#3 (meshlet LOD chain) pad loop spread over the lanes (notes/gpu-culling-rewrite.md).
# gi = 0xd070067d.file: RefProbe#121 probe-GI gather + #414 reflection probe trace (notes/gpu-gi-rewrite.md).
# fogpar = 0xa9910db8.file: VFSCAT#235 volumetric fog, ONLY the merged early-exit VSM level search (notes/ally-gpu-budget.md s6).
#   It supersedes the full 'fog' rewrite (5th column; measured slower on the Ally, dropped): that file is upgraded / reverted.
# trvs / pbvs = LOAD-DEDUPE (notes/gpu-materials-trim.md): vertex shaders that re-load the same read-only dwords
#   right after writing outputs; the repeat is removed. trvs = 0x52c39db0.file (PB2TREE2 tree VS), pbvs = 0xfd4f418f.file
#   (PB2 meshlet VS). Separate items: A/B each alone. Expected ~0 if the driver already merges the loads.
# wdo14 = 0x1667d3a0.file: WDO#14 sun-shadow resolve, VSM page-flag loads de-duplicated (notes/gpu-wdo14-flag-dedupe.md).
# msv = 187 files: every meshlet vertex shader with its slot-uniform load chain scalarized (notes/gpu-rewrite-round3.md).
#   Files come from meshvs/splice_msv.py <msv_all_records.zip> --flat. NOT part of "all": it shares 0x52c39db0 / 0xfd4f418f
#   with trvs / pbvs (it supersedes them); apply/revert it by name only.
# lodu = 0x8d9282e6.file: MshLod#2 (63c07c21) wave-uniform fast path (notes/gpu-rewrite-round4.md). SAME FILE as mshlod
#   (MshLod#3): install one or the other, never both; NOT part of "all" (apply/revert by name). File from
#   meshvs/splice_msv.py <cull4_records.zip> --flat. RADV note: the kernel already uses wave ops (no NGG concern: CS).
#
# Put this script next to the folder "replacement/" (gpu-shaders/replacement/*.file from the build PC).
# Game folder: auto-detected from the Steam library folders, or set NIOH3_DIR=/path/to/steamapps/common/Nioh3.
# Originals are backed up once to ${BACKUP_DIR:-$HOME/.local/share/nioh3-shader-backup}/ (SHA-256 checked) before the
# first overwrite; revert restores that exact file. Steam "Verify integrity of game files" also restores everything.
# Refuses while Nioh3.exe is running (the files are read at startup / PSO preload), and refuses to touch a file that is
# neither the known original nor the known replacement (= game updated: rebuild the replacement first).
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPL_DIR="${REPL_DIR:-$HERE/replacement}"
BACKUP_DIR="${BACKUP_DIR:-$HOME/.local/share/nioh3-shader-backup}"

